class.description:
A [PathInfo] is returned by [method PathPrefixServer.resolve] and [method PathPrefixServer.resolve_safe]. It holds the path as given, its canonical prefixed form, its OS path and the facts of its prefix, so that callers do not have to compute them one by one. It is read-only after creation.
[codeblocks]
[gdscript]
var info := PathPrefixServer.resolve("USER://saves\\a.json")
if info.valid:
	print(info.local_path)  # user://saves/a.json
	print(info.global_path) # The OS path inside the user data folder.
else:
	push_error(info.error_message)
[/gdscript]
[csharp]
PathInfo info = PathPrefixServer.Resolve("USER://saves\\a.json");
if (info.Valid)
{
    GD.Print(info.LocalPath); // user://saves/a.json
    GD.Print(info.GlobalPath); // The OS path inside the user data folder.
}
else
{
    GD.PushError(info.ErrorMessage);
}
[/csharp]
[/codeblocks]
